2	import { Context, Service } from '@deepseek-ai/cordis'
3	import { extname } from 'node:path'
4	import { access, constants, readFile, rename, writeFile } from 'node:fs/promises'
5	import { setTimeout as delay } from 'node:timers/promises'
6	import { fileURLToPath, pathToFileURL } from 'node:url'
7	import * as yaml from 'js-yaml'
8	
9	const JsExpr = new yaml.Type('tag:yaml.org,2002:js', {
10	  kind: 'scalar',
11	  resolve: (data) => typeof data === 'string',
12	  construct: (data) => ({ __jsExpr: data }),
13	  predicate: isJsExpr,
14	  represent: (data) => data['__jsExpr'],
15	})
16	
17	/**
18	 * The entry-list YAML dialect: `!!js` scalars round-trip as expression nodes
19	 * the Loader evaluates at entry activation. Exported so config tooling
20	 * (`dsh --dump-config`) parses and prints exactly the dialect this include
21	 * mounts.
22	 */
23	export const entryListSchema = yaml.JSON_SCHEMA.extend(JsExpr)
24	
25	const schema = entryListSchema
26	
27	const writable: Record<string, string> = {
28	  '.json': 'application/json',
29	  '.yaml': 'application/yaml',
30	  '.yml': 'application/yaml',
31	}
32	
33	const supported = new Set(Object.keys(writable))
34	
35	const WRITE_RETRY_LIMIT = 10
36	const WRITE_RETRY_DELAY_MS = 50
37	
38	function retryableWriteError(error: unknown): boolean {
39	  const code = (error as NodeJS.ErrnoException | null)?.code
40	  return code === 'EACCES' || code === 'EBUSY' || code === 'EPERM'
41	}
