43	/**
44	 * Apply patch lists to an entry list — THE patch semantics of this include,
45	 * shared by mounting (`applyPatches`) and offline config tooling
46	 * (`dsh --dump-config`) so a dump can never drift from what boots. The input
47	 * is never mutated and the result is always detached from it (even with no
48	 * patches): patching or mounting shared entry objects would bake earlier
49	 * values into the cached parse, so repeated application (config hot-reloads)
50	 * could never revert a removed or changed patch. Inserted entries are indexed
51	 * as they are added, so a later patch in the same list can target a row an
52	 * earlier patch inserted. A patch that matches nothing warns and is skipped.
53	 * @param data - the parsed entry list (JSON-safe plain data).
54	 * @param patches - the patch list to apply, in order.
55	 * @param warn - sink for skipped-patch diagnostics (printf-style, `%C` = code).
56	 * @returns a detached entry list with every applicable patch applied.
57	 */
58	export function applyEntryPatches(
59	  data: EntryOptions[],
60	  patches: PatchOptions[] | undefined,
61	  warn: (message: string, ...args: any[]) => void,
62	): EntryOptions[] {
63	  data = structuredClone(data)
64	  if (!patches?.length) return data
65	
66	  const entryMap = new Map<string, EntryOptions>()
67	  const buildMap = (entries: EntryOptions[]) => {
68	    for (const entry of entries) {
69	      if (entry.id) entryMap.set(entry.id, entry)
70	      if (entry.group && Array.isArray(entry.config)) {
71	        buildMap(entry.config)
72	      }
73	    }
74	  }
75	  buildMap(data)
76	
77	  for (const patch of patches) {
78	    const { id, insert, name, ...overrides } = patch
79	
80	    if (insert) {
81	      if (id) {
82	        const target = entryMap.get(id)
83	        if (!target) {
84	          warn('patch insert: entry %C not found', id)
85	          continue
86	        }
87	        if (!target.group) {
88	          warn('patch insert: entry %C is not a group', id)
89	          continue
90	        }
91	        if (!Array.isArray(target.config)) target.config = []
92	        target.config.push(...insert)
93	      } else {
94	        data.push(...insert)
95	      }
96	      // Index what this patch added so a LATER patch in the same list can
97	      // target it. Patch lists compose one layer per source (each bundle
98	      // layer, then the user's, then `--patch` overlays), and a layer must be
99	      // able to configure or disable a row an earlier layer inserted; without
100	      // this, inserted rows were silently unpatchable.
101	      buildMap(insert)
102	      continue
103	    }
104	
105	    if (!id) {
106	      warn('patch: id is required for non-insert patches')
107	      continue
108	    }
109	
110	    const target = entryMap.get(id)
111	    if (!target) {
112	      warn('patch: entry %C not found', id)
113	      continue
114	    }
115	
116	    if (name && name !== target.name) {
117	      warn('patch: name mismatch for %C (expected %C, got %C), skipping', id, target.name, name)
118	      continue
119	    }
120	
121	    for (const [key, value] of Object.entries(overrides)) {
122	      if (key === 'id') continue
123	      target[key] = value
124	    }
125	  }
126	
127	  return data
128	}
