130	type ConfigUpdateStage = 'read' | 'parse' | 'validate'
131	
132	interface ReadCandidate {
133	  content: string
134	  data: EntryOptions[]
135	}
136	
137	class ConfigFileError extends Error {
138	  constructor(public readonly stage: ConfigUpdateStage, path: string, cause: unknown) {
139	    super(`failed to ${stage} config file ${path}`, { cause })
140	    this.name = 'ConfigFileError'
141	  }
142	}
143	
144	/** Runtime patch applied to entries loaded from an included config file. */
145	export interface PatchOptions {
146	  id?: string
147	  insert?: EntryOptions[]
148	  name?: string
149	  config?: any
150	  group?: boolean | null
151	  disabled?: boolean | null
152	  inject?: any
153	  intercept?: any
154	  isolate?: any
155	  [key: string]: any
156	}
157	
158	/** Config namespace for the file-backed include loader. */
159	export namespace Include {
160	  /** Config for a file-backed loader subtree. */
161	  export interface Config {
162	    /** YAML or JSON path resolved from `ctx.baseUrl`. */
163	    path: string
164	    /** Entry list written when the file does not already exist. */
165	    initial?: any[]
166	    /** Runtime patches applied after reading the file. */
167	    patches?: PatchOptions[]
168	    /** Enables loader apply/reload/unload logs for this subtree. */
169	    enableLogs?: boolean
170	  }
171	}
172	
173	/** Loader entry tree backed by a YAML or JSON file. */
174	export class Include extends EntryTree {
175	  static inject = ['loader']
176	
177	  // Tree-carrier marker (the Group plugin declares the same): this config is
178	  // entry and patch lists, so the Loader's `internal/config` interpolation
179	  // keeps it literal — a `!!js` expression inside a nested row's config
180	  // belongs to that row's fiber, resolving lazily in the row's own context.
181	  // Include's own fields (`path`, `enableLogs`) therefore stay literal too.
182	  static readonly [EntryGroup.key] = true
183	
184	  public filename: string
185	  private type?: string
186	  private readonly: boolean
187	  private content?: string
188	  private data?: EntryOptions[]
189	  private writeTask?: NodeJS.Timeout | undefined
190	  private pendingWrite?: EntryOptions[]
191	  private writeQueue: Promise<void> = Promise.resolve()
192	  private applyQueue: Promise<unknown> = Promise.resolve()
193	
194	  constructor(ctx: Context, public config: Include.Config) {
195	    super(ctx)
196	    this.enableLogs = config.enableLogs ?? ctx.fiber.entry?.parent.tree.enableLogs ?? false
197	    this.filename = fileURLToPath(new URL(this.config.path, this.ctx.baseUrl))
198	    const ext = extname(this.filename)
199	    if (!supported.has(ext)) {
200	      throw new Error(`extension "${ext}" not supported`)
201	    }
202	    this.type = writable[ext]
203	    this.readonly = !this.type
204	    this.ctx.baseUrl = new URL('.', pathToFileURL(this.filename)).href
205	
206	    ctx.on('internal/update', async (config, _, next) => {
207	      if (config.path !== this.config.path) return next()
208	      await this.enqueue(async () => {
209	        const data = this.applyPatches(this.data!, config.patches)
210	        await this.root.update(data)
211	        this.config = config
212	      })
213	    })
214	  }
215	
216	  /**
217	   * Serialize one child-tree mutation behind every earlier one. The group's
218	   * transactional `update` is not reentrant: two concurrent applies (the init
219	   * apply racing an HMR-triggered refresh from the watcher's initial scan)
220	   * interleave create and rollback on the same entries and strand the include
221	   * fiber without settling, so every apply path funnels through this queue.
222	   * A predecessor's failure is its own caller's outcome and never gates the
223	   * next task.
224	   */
225	  private enqueue<T>(task: () => Promise<T>): Promise<T> {
226	    const run = this.applyQueue.then(task, task)
227	    this.applyQueue = run.then(() => {}, () => {})
228	    return run
229	  }
230	
231	  private async checkAccess() {
232	    if (!this.type) return
233	    try {
234	      await access(this.filename, constants.W_OK)
235	    } catch {
236	      this.readonly = true
237	    }
238	  }
239	
240	  private async read(forced = false): Promise<ReadCandidate | undefined> {
241	    let content: string
242	    try {
243	      content = await readFile(this.filename, 'utf8')
244	    } catch (error) {
245	      throw new ConfigFileError('read', this.filename, error)
246	    }
247	    if (!forced && this.content === content) return
248	    let data: any
249	    try {
250	      if (this.type === 'application/yaml') {
251	        data = yaml.load(content, { schema })
252	      } else if (this.type === 'application/json') {
253	        data = JSON.parse(content)
254	      } else {
255	        const module = await import(/* @vite-ignore */ this.filename)
256	        data = module.default || module
257	      }
258	    } catch (error) {
259	      throw new ConfigFileError('parse', this.filename, error)
260	    }
261	    if (!Array.isArray(data)) {
262	      throw new ConfigFileError('validate', this.filename, new TypeError('config file must be a top-level array'))
263	    }
264	    return { content, data }
265	  }
266	
267	  private applyPatches(data: EntryOptions[], patches?: PatchOptions[]): EntryOptions[] {
268	    return applyEntryPatches(data, patches, (message, ...args) => {
269	      this.ctx.root.logger?.('loader').warn(message, ...args)
270	    })
271	  }
272	
273	  async* [Service.init]() {
274	    let candidate: ReadCandidate
275	    try {
276	      candidate = (await this.read(true))!
277	    } catch (error) {
278	      if (!(error instanceof ConfigFileError) || error.stage !== 'read' || (error.cause as NodeJS.ErrnoException)?.code !== 'ENOENT') throw error
279	      if (this.config.initial) {
280	        await this._writeFile(this.config.initial as any)
281	        candidate = (await this.read(true))!
282	      } else {
283	        throw new Error(`config file not found: ${this.filename}`)
284	      }
285	    }
286	
287	    yield () => this.stop()
288	    await this.apply(candidate)
289	  }
290	
291	  async stop() {
292	    await this.root.stop()
293	    await this.flushWrite()
294	  }
295	
296	  /**
297	   * Re-read the file and transactionally refresh child entries when content changed.
298	   * @returns a promise resolving after the new tree commits, or immediately when unchanged.
299	   * @throws when reading, parsing, validation, application, or rollback fails; the last good tree remains active when rollback succeeds.
300	   */
301	  async refresh() {
302	    // Read inside the queue so the changed-content check compares against the
303	    // predecessor's committed state, not a mid-apply snapshot.
304	    await this.enqueue(async () => {
305	      const candidate = await this.read()
306	      if (!candidate) return
307	      await this._apply(candidate)
308	    })
309	  }
310	
311	  private apply(candidate: ReadCandidate) {
312	    return this.enqueue(() => this._apply(candidate))
313	  }
314	
315	  private async _apply(candidate: ReadCandidate) {
316	    const data = this.applyPatches(candidate.data, this.config.patches)
317	    await this.root.update(data)
318	    this.content = candidate.content
319	    this.data = candidate.data
320	    await this.checkAccess()
321	  }
322	
323	  private async _writeFile(config: EntryOptions[]) {
324	    if (this.readonly) {
325	      throw new Error(`cannot overwrite readonly config`)
326	    }
327	    if (this.type === 'application/yaml') {
328	      this.content = yaml.dump(config, { schema })
329	    } else if (this.type === 'application/json') {
330	      this.content = JSON.stringify(config, null, 2)
331	    }
332	    await writeFile(this.filename + '.tmp', this.content!)
333	    for (let retry = 0; ; retry++) {
334	      try {
335	        await rename(this.filename + '.tmp', this.filename)
336	        return
337	      } catch (error) {
338	        if (!retryableWriteError(error) || retry >= WRITE_RETRY_LIMIT) throw error
339	        await delay((retry + 1) * WRITE_RETRY_DELAY_MS)
340	      }
341	    }
342	  }
343	
344	  private writeFile(config: EntryOptions[]) {
345	    clearTimeout(this.writeTask)
346	    this.pendingWrite = config
347	    this.writeTask = setTimeout(() => {
348	      void this.flushWrite()
349	    }, 0)
350	  }
351	
352	  private flushWrite(): Promise<void> {
353	    clearTimeout(this.writeTask)
354	    this.writeTask = undefined
355	    const config = this.pendingWrite
356	    this.pendingWrite = undefined
357	    if (config === undefined) return this.writeQueue
358	    const run = this.writeQueue.then(
359	      () => this._writeFile(config),
360	      () => this._writeFile(config),
361	    )
362	    this.writeQueue = run
363	    void run.catch((error) => {
364	      this.ctx.root.logger?.('loader').warn('failed to write config file %C', this.filename)
365	      this.ctx.root.logger?.('loader').warn(error)
366	    })
367	    return run
368	  }
369	
370	  /** Schedule a write of the current root entry data. */
371	  write() {
372	    this.context.emit('loader/config-update')
373	    return this.writeFile(this.root.data)
374	  }
375	}
376	
377	export default Include
